import{_ as a,o as t,c as o,ag as l}from"./chunks/framework.IxO3mcwW.js";const e="/getbiji-docs/images/book-01.png",r="/getbiji-docs/images/book-02.png",s="/getbiji-docs/images/book-03.png",p="/getbiji-docs/images/book-04.png",d="/getbiji-docs/images/book-05.png",n="/getbiji-docs/images/book-06.png",c="/getbiji-docs/images/book-07.png",g="/getbiji-docs/images/book-08.png",P=JSON.parse('{"title":"智能拍书","description":"","frontmatter":{},"headers":[],"relativePath":"capture/book.md","filePath":"capture/book.md","lastUpdated":1773147350000}'),h={name:"capture/book.md"};function b(u,i,m,_,x,k){return t(),o("div",null,[...i[0]||(i[0]=[l('<h1 id="智能拍书" tabindex="-1">智能拍书 <a class="header-anchor" href="#智能拍书" aria-label="Permalink to &quot;智能拍书&quot;">​</a></h1><blockquote><p>拍照即用，3秒数字化，纸质书笔记永不丢失！</p></blockquote><p>高质量 OCR 提取书页上的文字，智能识别书籍信息，AI 自动整理成结构化笔记，并分类到对应书籍下，让纸质书阅读痕迹变成可搜索、可应用的数字资产。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>纸质书阅读</strong>：将书中划线、批注快速数字化保存</li><li><strong>图书摘录</strong>：重要段落、金句、观点一拍即存</li><li><strong>学术研究</strong>：论文、专业书籍内容提取和整理</li><li><strong>学习复习</strong>：快速回顾多本书的核心要点</li><li><strong>写作素材</strong>：AI助手帮你在海量读书笔记中找到书中观点</li></ul><h2 id="不适用的场景" tabindex="-1">不适用的场景 <a class="header-anchor" href="#不适用的场景" aria-label="Permalink to &quot;不适用的场景&quot;">​</a></h2><ul><li>非文字内容（如乐谱、地图、纯图片等）</li><li>字迹模糊或页面破损严重的书页</li></ul><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>打开 APP，点击首页底部+更多入口</p></li><li><p>点击「智能拍书」，对准书页内容进行拍摄</p><p>系统会自动矫正角度、去除阴影、优化清晰度</p></li><li><p>默认是自动识别书籍，右边同时会展示最近识别过的书籍（如有），可以手动切换</p></li><li><p>点下一步，AI 开始智能处理：提取文字内容 → 识别并确认书籍信息 → 生成结构化笔记</p><p>确认书籍信息，如识别有误可手动搜索或添加</p></li><li><p>笔记自动归类到对应书籍下，支持继续拍照或查看整理结果</p></li><li><p>可随时通过搜索或 AI 对话快速定位笔记内容</p></li><li><p>同时，支持跳转到对应书籍的章节段落查看原文</p></li><li><p>所有书籍笔记，可以通过首页左上角的菜单进入查看，会以书籍视图形式呈现</p></li></ol><h2 id="拍照限制" tabindex="-1">拍照限制 <a class="header-anchor" href="#拍照限制" aria-label="Permalink to &quot;拍照限制&quot;">​</a></h2><ul><li>单次最多支持识别 5 张图片，确保文字清晰可见</li><li>避免手指遮挡重要文字区域</li><li>光线充足的环境下拍摄效果更佳</li></ul><h2 id="特别说明" tabindex="-1">特别说明 <a class="header-anchor" href="#特别说明" aria-label="Permalink to &quot;特别说明&quot;">​</a></h2><ul><li>拍书整理仅用于个人学习和笔记管理，请遵守相关版权法规；</li><li>支持批量上传多张图片（单次最多5张），系统会按顺序处理并归类；</li><li>首次使用建议从熟悉的书籍开始，体验 AI 识别的准确性。</li></ul><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+e+'" alt="智能拍书入口" style="width:180px;border-radius:8px;"><img src="'+r+'" alt="拍摄书页" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="识别书籍" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="AI处理" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="结构化笔记" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="书籍视图" style="width:180px;border-radius:8px;"><img src="'+c+'" alt="搜索定位" style="width:180px;border-radius:8px;"><img src="'+g+'" alt="原文跳转" style="width:180px;border-radius:8px;"></div>',15)])])}const q=a(h,[["render",b]]);export{P as __pageData,q as default};
